//! 🧫️ Shared literal painted-path test input contract.
use super::*;
pub(super) fn input(source:&serde_json::Value)->PaintedPathPreparation{let q=&source["query"];PaintedPathPreparation{transform:serde_json::from_value(q["transform"].clone()).unwrap(),flatness:q["flatness"].as_f64().unwrap(),fill:q["fill"].as_bool().unwrap(),fill_rule:serde_json::from_value(q["fillRule"].clone()).unwrap(),stroke:(!q["stroke"].is_null()).then(||PaintedPathStroke{width:q["stroke"]["width"].as_f64().unwrap(),cap:serde_json::from_value(q["stroke"]["cap"].clone()).unwrap(),join:serde_json::from_value(q["stroke"]["join"].clone()).unwrap(),dash:serde_json::from_value(q["stroke"]["dash"].clone()).unwrap()}),limits:PaintedRegionLimits{max_segments:65536,max_points:262144,max_contours:65536,max_work:1000000000}}}
